/* Guided registration: locate (optional) → define shape → review → compare. */
function simplePoint(){const r=state.lookupResult;if(r?.status==='point'||r?.status==='candidate'&&r.method!=='registration')return {lat:r.lat,lng:r.lng,method:r.method};if(state.lotConfirmed&&Number.isFinite(state.lot.lat)&&Number.isFinite(state.lot.lng))return {lat:state.lot.lat,lng:state.lot.lng,method:state.lookupContext?.method};return null}
function simpleLocationStatus(){const r=state.lookupResult,p=simplePoint();if(r?.status==='error'||r?.status==='unresolved')return lookupResult();if(!p&&r?.status!=='candidate')return '<p class="parcel-location-optional">A localização pode ser informada depois. Você já pode começar pelas medidas.</p>';return `<section id="lookup-result" class="simple-point" tabindex="-1" aria-label="Localização selecionada"><span class="simple-point-icon">${icon('check')}</span><div><strong>${r?.status==='candidate'?'Exemplo encontrado':'Localização marcada'}</strong><p>${p?`${number(p.lat,6)}, ${number(p.lng,6)}`:'Matrícula do conjunto demonstrativo'} · João Pessoa / PB</p></div><button class="btn" data-action="open-location-picker" aria-label="Alterar localização no mapa">Alterar</button></section>`}
function simpleMeasures(){return parcelFormView()}
function simpleFindView(){const point=simplePoint(),candidate=state.lookupResult?.status==='candidate';return `<div class="simple-start">${simpleMeasures()}<section class="simple-locate panel"><div class="simple-section-title"><span>2</span><h2>Localização do terreno</h2></div><p class="simple-section-description">Opcional: localize o entorno ou desenhe os limites sobre o mapa.</p><button class="simple-map-launch" data-action="open-location-picker"><span class="simple-map-art" aria-hidden="true"><i></i><b>${icon('pin')}</b></span><strong>${point?'Ajustar localização no mapa':'Marcar terreno no mapa'}</strong><span>Aérea, ruas e relevo 3D · toque para explorar ${icon('arrowRight')}</span></button>${simpleLocationStatus()}<button class="btn parcel-direct-map" data-parcel-command="edit-map">${icon('draw')}Delimitar terreno no mapa</button><details class="simple-lookup-details" id="other-location-methods" ${state.simpleLookupOpen?'open':''}><summary>Informar coordenadas, matrícula ou endereço</summary>${lookupFields(false)}</details>${candidate?`<div class="parcel-example-result"><p>Encontramos um lote de demonstração. Você pode abrir suas medidas fictícias ou cadastrar seu próprio terreno.</p>${btn('Usar lote de exemplo','check','quick-candidate')}</div>`:''}<div class="parcel-location-guide"><h3>Um ponto localiza. O perímetro define.</h3><p>As imagens ajudam a reconhecer o terreno. Para medir o lote, informe seu formato, desenhe o perímetro ou importe as coordenadas dos vértices.</p><div>${icon('shield')}Geometria informada pelo usuário · sem validação cadastral</div></div></section></div><div class="simple-outcome"><span>${icon('building')}Casa, apartamentos, salas comerciais e flats</span><p>Compare área total, área após recuos e área computável. Revise o desenho antes de simular.</p><small>Cadastro geométrico estimado · regras e cenários de demonstração.</small></div>`}
function parseMeasure(text){return ParcelGeometry.num(text)}
function quickDemo(){selectLot(lots[0].id,{method:'example',verified:false});window.ViabilUsage.run(()=>{state.step=2;state.analyzed=true;render();focusMain()})}
function quickCandidate(){const r=state.lookupResult;if(!r||r.status!=='candidate')return;confirmLookup();window.ViabilUsage.run(()=>{state.step=2;state.analyzed=true;render();focusMain()})}
function resetSimpleStudy(){state.lot=lots[0];state.lotConfirmed=false;state.lookupResult=null;state.lookupContext=null;state.lookupDirty=false;state.parcelDirty=false;state.parcelDraft=newParcelDraft();state.mapPickedPoint=null;state.lookupValues={latitude:'',longitude:'',registration:'',office:'',address:''};state.quickMeasureValues={area:'',frontage:''};state.simpleLookupOpen=false;state.simpleGeometryOpen=false;state.customPolygon=null;state.drawing=false}
document.addEventListener('toggle',e=>{if(e.target.id==='other-location-methods'){state.simpleLookupOpen=e.target.open;if(e.target.open&&state.lookupMode==='map'){state.lookupMode='coordinates';render();$('#other-location-methods summary').focus({preventScroll:true})}}},true);
